if not (R/'LAT-001.cache.Guide-Ibn-Tibbon.json').exists():
 inv=json.loads((R/'LAT-001.inventory-cache.json').read_text())['books']
 b=next(b for b in inv if b['title']=='Guide for the Perplexed' and b.get('versionTitle')=='Moreh Nevuchim, translated by Ibn Tibon' and b.get('language')=='Hebrew')
