rows=[]
def get(file,path):
 d=json.loads((R/file).read_text());s=d['text']
 for k in path:s=s[k-1] if isinstance(k,int) else s[k]
 return d,re.sub('<[^>]*>','',s)
def add(id,work,file,path,locator,quote,context,interp,mention='direct',author=None,extra=None):
 d,s=get(file,path);assert quote in s,(id,quote)
 url=sel[work]['json_url'] if work in sel else ''
 edition=d.get('versionTitle') or str(d.get('versions'))
 if file=='LAT-001.cache.Guide-Ibn-Tibbon.json':
  inv=json.loads((R/'LAT-001.inventory-cache.json').read_text())['books'];url=next(b['json_url'] for b in inv if b['title']==work and b.get('versionTitle')==d['versionTitle'] and b.get('language')=='Hebrew')
 limitations=['Independent review pending; digital text not manuscript/print collated.']
 if extra:limitations+=extra
 rows.append(dict(id=id,corpus_id='later-literature',work=work,locator=locator,url=url,edition=edition,language='he',mention_type=mention,parent_source_id=None,quote=quote,context=context,checks=dict(primary_read=True,quote_verified=True,context_checked=True,attribution_verified=True,commentaries_checked=False,interpretation_prepared=True,independent_reviewed=False),interpretation=interp,epistemic_type='traditional_commentary',reviewers=['/root/commentaries'],task_id='LAT-001',limitations=limitations,accessed_at='2026-10-09',author=author,text_path=path,quote_normalization='HTML markup stripped; Hebrew characters retained'))
add('maharal-gevurot-hashem-47-53','Gevurot Hashem','LAT-001.cache.Gevurot_Hashem.json',['',47,53],'47:53','והרמז בזה על שר של מצרים, נקרא "רוכבו", ומצרים הם הסוס אליו נחשבים','Song at Sea, Exodus15:1: riding evokes pride and the ruler of Egypt; paragraph interprets throwing the prince into sea.','Maharal gives a governing-prince/nation allegory: Egypt stands to its prince as horse to rider. This is symbolic hierarchy; no horse traveling between worlds is specified.',author='Maharal')
add('maharal-gevurot-hashem-29-9','Gevurot Hashem','LAT-001.cache.Gevurot_Hashem.json',['',29,9],'29:9 (context 29:4–12)','למה דוקא היו רוכבים על חמור, ולא [על] סוס שנברא בין השמשות','Reads Abraham/Moses/Messiah’s donkey through materiality, rising above material world, and twilight creation; 29:8 explicitly calls the donkey natural like other donkeys; 29:12 interprets its sameness through one rank/function.','Horse is a contrast in a donkey-centered allegory of materiality. The rhetorical alternative does not assert that a particular horse was created at twilight. Nor does the passage describe horse-mediated spiritual travel.',mention='indirect',author='Maharal')
add('maharal-beer-hagolah-well6-3-1','Be\'er HaGolah','LAT-001.cache.Be_er_HaGolah.json',['Well 6',3,1],'Well 6:3:1','שהגלגל דומה אל הקרון, שהקרון הולך על ידי תנועת הסוס המושך הקרון אחריו','Explains competing opinions in Pesachim94b about moving stars and sphere; distinguishes which supplies motion.','Horse pulling cart is an analogy for causal motion of star and sphere within Maharal’s reading, rather than an actual celestial horse.',mention='indirect',author='Maharal')
add('hida-chomat-anakh-2kings-6-18-1','Chomat Anakh on II Kings','LAT-001.cache.Chomat_Anakh_on_II_Kings.json',[6,18,1],'6:18:1','הגם שהיו סוסי ורכב אש לשומרו. בחר בזה לכמה טעמים.','Explains Elisha choosing blindness despite fiery horse/chariot protection: sparing lives, sanctifying God’s name among nations, and prompting repentance. Ends that some of this appears in commentators.','Fiery horses/chariots have protective and potentially destructive function; Hida emphasizes choosing nonlethal blindness and mercy. No interworld transport stated.',author='Chida')
add('hida-midbar-kedemot-peh-1','Midbar Kedemot','LAT-001.cache.Midbar_Kedemot.json',['Letter Peh',1],'Letter Peh:1','כי התורה היא פרד"ס והוא חיסר סמך ונשאר פרד','Entry on plain Torah meaning as body and secret as soul; associates Pardes minus sod with pered and cites Psalm32:9 horse/mule lacking understanding.','Horse/mule verse supports a rebuke of rejecting secret interpretation; pered/Pardes wordplay concerns methods of Torah interpretation. This does not turn the horse into a conveyance between realms.',author='Chida')
add('hida-midbar-kedemot-zayin-8','Midbar Kedemot','LAT-001.cache.Midbar_Kedemot.json',['Letter Zayin',8],'Letter Zayin:8','דבערבי קורין לסוסיא נקבה רמך. וכחל במ"ק פרד.','Entry on sexual transgression: letters of loaf-of-bread phrase encode two punishing appointed entities; cites Aspaklaria HaMeira in name of R. Shimshon of Ostropoli; adds own Arabic lexical observation.','Recorded kabbalistic/linguistic association uses mare and mule terms in names/letter arithmetic. Attribution chain is Hida reporting another work; the cited earlier work itself not read. No spiritual horse travel mechanism.',author='Chida',extra=['Reported source chain not independently checked: Aspaklaria HaMeira page76, beginning Kedoshim, citing Shimshon of Ostropoli.'])
add('hida-midbar-kedemot-mem-38','Midbar Kedemot','LAT-001.cache.Midbar_Kedemot.json',['Letter Mem',38],'Letter Mem:38','כס"א ר"ת כסף סוסים אשה','King’s three accumulation restrictions; observance associated with enduring throne.','Horse is one element of mnemonic for royal limits; no mystical equine travel.',author='Chida')
add('rambam-guide-1-70-4','Guide for the Perplexed','LAT-001.cache.Guide-Ibn-Tibbon.json',['Part 1','',70,4],'I:70:4 (context I:70:1–9)','איך בארו יחסו ית׳ לגלגל, ושהוא כלי לו אשר בו ינהיג המציאות','Explains riding as governing; rider outside/independent of mount (paragraph3), cites Genesis Rabbah horse subordinate to rider and Habakkuk3:8; interprets contents of Aravot as powers rather than bodily objects in a place.','Rambam uses horse/rider analogy to explain God’s governance through celestial sphere and independence from it. This concerns causal rule, not God corporeally riding a horse or a horse ferrying souls.',author='Rambam',extra=['Quoted in medieval Ibn Tibbon Hebrew translation; Arabic original not collated.'])
add('rambam-guide-1-70-7','Guide for the Perplexed','LAT-001.cache.Guide-Ibn-Tibbon.json',['Part 1','',70,7],'I:70:7','וזאת הראיה על היות שם ׳מרכבה׳ נופל על ארבעה מן הסוסים.','Uses Solomon’s price ratio in I Kings10:29 to interpret chariot as four horses, then four living beings carrying throne called merkavah by analogy.','A named conceptual bridge from ordinary chariot/horses to merkavah terminology. Four-horse count is Rambam’s interpretive inference from price ratio; does not identify Ezekiel’s beings as literal horses.',author='Rambam',extra=['Quoted in medieval Ibn Tibbon Hebrew translation; Arabic original not collated.'])
add('rambam-guide-2-43-4','Guide for the Perplexed','LAT-001.cache.Guide-Ibn-Tibbon.json',['Part 2','',43,4],'II:43:4','ודע, כי כמו שיראו הנביאים דברים שהרצון בהם – משל כ׳נרות זכריה׳ וה׳סוסים׳ וה׳הרים׳','Prophetic parables and imaginative faculty; some explained within vision, some after waking; distinguishes symbolic things and meaningful names.','Rambam explicitly classes Zechariah’s horses and mountains among prophetic parables. Supports symbolic interpretation rather than literal existence/travel of those visionary horses.',author='Rambam',extra=['Quoted in medieval Ibn Tibbon Hebrew translation; Arabic original not collated.'])
