 s=h.pop('text');h['text_sha256']=hashlib.sha256(s.encode()).hexdigest();h['equine_token_candidate']=bool(pat.search(s));pos=s.find('סוס') if 'סוס' in s else min(s.find(q) for q in h['queries'] if q in s);h['excerpt']=s[max(0,pos-100):pos+350]
