(R/'LAT-001.availability.json').write_text(json.dumps(dict(schema_version=1,inventory_url=M['inventory_url'],catalogued=inv,excluded_attribution_trap='Chidushei Agadot series is Maharsha, not Maharal; Sefaria About description checked.',unlocated_in_export_index=['Maharal Hiddushei Aggadot','Birkei Yosef'],note='Catalog presence is not access/read/search completeness.'),ensure_ascii=False,indent=2))
